import{_ as d,o as e,c as a,a2 as r}from"./chunks/framework.Dj7FWXx_.js";const _=JSON.parse('{"title":"认识萌卡 NT","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":1789552862000}'),o={name:"guide/index.md"};function n(i,t,s,c,l,h){return e(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="认识萌卡-nt" tabindex="-1">认识萌卡 NT <a class="header-anchor" href="#认识萌卡-nt" aria-label="Permalink to &quot;认识萌卡 NT&quot;">​</a></h1><p>萌卡 NT（Mengka NT）是一套面向 QQ NT 协议的跨平台机器人框架。它把账号、设备指纹、连接节点、插件服务和运行状态集中到 Web 管理界面，并通过插件 WebSocket 与 Node.js SDK 提供消息、联系人、群管理及扩展业务能力。</p><div class="warning custom-block"><p class="custom-block-title">当前站点状态</p><p>这是萌卡 NT 2.0 官网的预发布版本。框架当前正式版为 <strong>v2.3.8</strong>，请只从官方 GitHub Releases 下载外发包。</p></div><h2 id="核心能力" tabindex="-1">核心能力 <a class="header-anchor" href="#核心能力" aria-label="Permalink to &quot;核心能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th>能力</th></tr></thead><tbody><tr><td>账号管理</td><td>多 QQ 账号统一管理，支持缓存、密码登录及安全验证流程</td></tr><tr><td>协议与设备</td><td>为账号独立选择协议、设备指纹和连接节点</td></tr><tr><td>消息与群</td><td>消息收发、联系人、群成员与常用群管理能力</td></tr><tr><td>插件系统</td><td>正向/反向 WebSocket、Node.js SDK、WebUI SDK 与统一 action 结果</td></tr><tr><td>可视化管理</td><td>账号、节点、插件、容器、令牌、日志和消息面板</td></tr></tbody></table><h2 id="支持平台" tabindex="-1">支持平台 <a class="header-anchor" href="#支持平台" aria-label="Permalink to &quot;支持平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>平台</th><th>架构</th><th>正式包</th></tr></thead><tbody><tr><td>Windows</td><td>AMD64 / x86_64</td><td><code>mengka-nt-*-windows-amd64.zip</code></td></tr><tr><td>Linux</td><td>AMD64 / x86_64</td><td><code>mengka-nt-*-linux-amd64.tar.gz</code></td></tr><tr><td>Linux</td><td>ARM64 / AArch64</td><td><code>mengka-nt-*-linux-arm64.tar.gz</code></td></tr></tbody></table><p><a href="/guide/getting-started.html">开始安装 →</a></p>',8)])])}const u=d(o,[["render",n]]);export{_ as __pageData,u as default};
